INSERT INTO jlpt_grammar (pattern, meaning_ko, meaning_ja, jlpt_level, formation, formation_detail, category, example_sentences, usage_notes, sort_order) VALUES
('〜ところを', '~한데(도) / ~중에', 'ある状況・場面なのに、の意。挨拶の定型にも使う。', 'N1', '動詞・い形 / 名詞の + ところを', '주로 격식 인사. 「お忙しいところを」「お休みのところを」.', 'contrast', '[{"ja": "お忙しいところをお越しいただき、ありがとうございます。", "ko": "바쁘신 중에 와 주셔서 감사합니다.", "highlight": "お忙しいところを"}]', '비즈니스 인사 관용. 메일·회의 서두.', 131),
('〜ともなく', '무심코 ~ / 딱히 ~하는 것도 아니게', '無意識に、はっきりした目的なく行う。', 'N1', '動詞辞書形 + ともなく / ともなしに', '「見るともなく」「聞くともなしに」 등 지각동사와 자주.', 'manner', '[{"ja": "見るともなく窓の外を眺めていた。", "ko": "무심코 창밖을 바라보고 있었다.", "highlight": "見るともなく"}]', '소설·묘사체. 무의식적 동작.', 132),
('〜とはいえ', '~라고는 해도', '〜ても、実際は、という逆接。', 'N1', '名詞 / 普通形 + とはいえ', '예상과 현실의 괴리. 문어·회화 모두.', 'contrast', '[{"ja": "専門家とはいえ、すべてを知っているわけではない。", "ko": "전문가라고는 해도 모든 것을 아는 것은 아니다.", "highlight": "専門家とはいえ"}]', '단정 후 단서. 「〜とはいうものの」와 유사.', 133),
('〜といったらない', '더없이 ~하다', '程度が極端で言葉にできないほどだ。', 'N1', 'い形 / 名詞 + といったらない', '강한 감정·정도. 「〜といったらありはしない」도.', 'degree', '[{"ja": "締め切り前の忙しさといったらない。", "ko": "마감 전 바쁨은 이루 말할 수 없다.", "highlight": "忙しさといったらない"}]', '감탄·불평 강조(회화).', 134),
('〜まい', '~하지 않겠다 / ~지 않을 것이다', '否定の意志または否定の推量。', 'N1', '動詞辞書形 + まい', '①의지: 「二度とするまい」 ②추량: 「来るまい」. する→するまい/すまい. 一段동사는 「見るまい/見まい」 둘 다 가능.', 'conjecture', '[{"ja": "二度と同じ失敗はするまいと誓った。", "ko": "두 번 다시 같은 실수는 하지 않겠다고 다짐했다.", "highlight": "するまい"}]', '문어적. 「〜ではあるまい」(추량 부정).', 135),
('〜ごとき', '~와 같은 / ~따위', '〜のような、または軽視の意。', 'N1', '名詞の / 動詞た形 + ごとき(名詞) / ごとく(動詞)', '①비유: 「氷のごとく」 ②겸양·경시: 「私ごとき」「彼ごとき」.', 'manner', '[{"ja": "私ごときがお役に立てるでしょうか。", "ko": "저 따위가 도움이 될 수 있을까요.", "highlight": "私ごとき"}]', '문어. 겸양(자기) 또는 경시(타인).', 136),
('〜ながらも', '~하면서도', '〜のに、〜けれども、という逆接。', 'N1', '動詞ます形 / い形 / な形 / 名詞 + ながらも', '동시·역접. 「残念ながらも」「狭いながらも」.', 'contrast', '[{"ja": "狭いながらも、住み心地のよい部屋だ。", "ko": "좁지만 살기 좋은 방이다.", "highlight": "狭いながらも"}]', '회화·문어. 대비 강조.', 137),
('〜ようものなら', '~하기라도 하면 (큰일)', 'もし〜したら大変なことになる、の意。', 'N1', '動詞意向形 + ものなら', '극단적 가정 + 부정적 결과.', 'condition', '[{"ja": "納期を破ろうものなら、取引先の信頼を失うことになる。", "ko": "납기를 어기기라도 하면 거래처의 신뢰를 잃게 된다.", "highlight": "破ろうものなら"}]', '경고·과장. IT현장: 장애·납기 맥락.', 138),
('〜が最後', '일단 ~하면 (끝장)', 'いったん〜したら、必ず悪い結果になる。', 'N1', '動詞た形 + が最後', '「〜たら最後」도 같음.', 'condition', '[{"ja": "あの上司に捕まったが最後、話が一時間は終わらない。", "ko": "저 상사한테 붙잡히면 끝, 이야기가 한 시간은 안 끝난다.", "highlight": "捕まったが最後"}]', '필연적 악결과. 회화에서 과장.', 139),
('〜きり', '~한 채 (그대로)', '〜したまま、その後変化がない。', 'N1', '動詞た形 + きり', '「〜たきり〜ない」 형태가 많음.', 'time', '[{"ja": "彼は朝出かけたきり、まだ戻らない。", "ko": "그는 아침에 나간 채 아직 돌아오지 않는다.", "highlight": "出かけたきり"}]', '상태 지속(주로 부정 동반).', 140),
('〜こととて', '~인지라 / ~이라서', '〜なので、という理由・弁解の硬い表現。', 'N1', '名詞の / 普通形 + こととて', '변명·사과 문맥. 격식·문어. 예문의 「慣れぬ」는 「慣れない」의 문어 부정형.', 'reason', '[{"ja": "慣れぬこととて、ご迷惑をおかけしました。", "ko": "익숙지 않은지라 폐를 끼쳤습니다.", "highlight": "慣れぬこととて"}]', '사과 정형. 비즈니스 격식.', 141),
('〜うと〜まいと', '~하든 안 하든', 'どちらの場合でも結果は関係ない。', 'N1', '動詞意向形 + と + 動詞辞書形 + まいと', '「〜うが〜まいが」도 동일.', 'contrast', '[{"ja": "参加しようとしまいと、君の自由だ。", "ko": "참가하든 말든 네 자유다.", "highlight": "しようとしまいと"}]', '무관함 강조.', 142),
('〜ものがある', '~한 데가 있다 / ~한 면이 있다', '何か強く感じられるものがある、の意。', 'N1', '普通形 + ものがある', '주관적 인상·평가.', 'degree', '[{"ja": "彼の努力には目を見張るものがある。", "ko": "그의 노력에는 눈여겨볼 만한 데가 있다.", "highlight": "目を見張るものがある"}]', '감상·평가.', 143),
('〜に足る', '~할 만하다', '〜する価値・資格が十分にある。', 'N1', '動詞辞書形 / 名詞 + に足る', '「信頼に足る」「満足に足る」. 부정 「〜に足りない」.', 'degree', '[{"ja": "彼は信頼に足る人物だ。", "ko": "그는 신뢰할 만한 인물이다.", "highlight": "信頼に足る"}]', '가치·자격 평가.', 144),
('〜べくもない', '~할 도리도 없다', '〜することは到底できない、の意。', 'N1', '動詞辞書形 + べくもない', 'する→すべくもない. 강한 불가능.', 'ability', '[{"ja": "真相は今となっては知るべくもない。", "ko": "진상은 이제 와서는 알 도리가 없다.", "highlight": "知るべくもない"}]', '문어. 불가능 강조.', 145),
('〜までもない', '~할 것까지도 없다', '〜する必要がないほど明らかだ。', 'N1', '動詞辞書形 + までもない', '「言うまでもない」 관용.', 'degree', '[{"ja": "言うまでもなく、品質が最優先だ。", "ko": "말할 것도 없이 품질이 최우선이다.", "highlight": "言うまでもなく"}]', '자명함 강조.', 146),
('〜ばこそ', '~하기 때문에(야말로)', '〜だからこそ、と理由を強調する。', 'N1', '動詞ば形 / い形ければ / 名詞であれば + こそ', '긍정적 이유 강조. 문어.', 'reason', '[{"ja": "努力すればこそ、成果が得られる。", "ko": "노력하기에 비로소 성과를 얻는다.", "highlight": "努力すればこそ"}]', '강한 이유 강조.', 147),
('〜なくしては', '~없이는 (불가능)', '〜がなければ〜できない、の意。', 'N1', '名詞 + なくしては', '뒤에 부정. 「〜なくして〜ない」.', 'condition', '[{"ja": "信頼なくしては、チームは機能しない。", "ko": "신뢰 없이는 팀은 기능하지 않는다.", "highlight": "信頼なくしては"}]', '필수 조건 강조.', 148),
('〜とばかりに', '~라는 듯이', 'いかにも〜という様子で。', 'N1', '普通形 / 名詞 + とばかりに', '말은 안 했지만 그런 태도로.', 'manner', '[{"ja": "待っていたとばかりに、彼は反論を始めた。", "ko": "기다렸다는 듯이 그는 반론을 시작했다.", "highlight": "待っていたとばかりに"}]', '태도·기색 묘사.', 149),
('〜んばかりに', '~할 듯이 / ~할 만큼', '今にも〜しそうなほど程度が高い。', 'N1', '動詞ない形(語幹) + んばかりに', 'する→せんばかり. 「あふれんばかり」.', 'degree', '[{"ja": "会場はあふれんばかりの観客で埋まった。", "ko": "회장은 넘칠 듯한 관객으로 가득 찼다.", "highlight": "あふれんばかりの"}]', '과장적 정도 묘사(문어).', 150),
('〜ともすると', '자칫하면', 'どうかすると〜しがちだ、の意。', 'N1', '副詞的に + ともすると / ともすれば', '뒤에 「〜がちだ」가 자주.', 'conjecture', '[{"ja": "ともすると初心を忘れがちだ。", "ko": "자칫하면 초심을 잊기 쉽다.", "highlight": "ともすると"}]', '경향·우려.', 151),
('〜ならいざ知らず', '~라면 몰라도', '〜なら別だが、そうでないなら、の意。', 'N1', '名詞 / 普通形 + ならいざ知らず', '대비로 뒤를 강조.', 'contrast', '[{"ja": "新人ならいざ知らず、ベテランがこのミスは困る。", "ko": "신입이라면 몰라도 베테랑이 이 실수는 곤란하다.", "highlight": "新人ならいざ知らず"}]', '예외 제시 후 본론 강조.', 152),
('〜てはいられない', '~하고 있을 수 없다', '〜する余裕や時間がない、の意。', 'N1', '動詞て形 + はいられない', '여유 없음. 「のんびりしてはいられない」.', 'manner', '[{"ja": "締め切りが近い。のんびりしてはいられない。", "ko": "마감이 가깝다. 한가하게 있을 수 없다.", "highlight": "してはいられない"}]', '절박함 표현.', 153),
('〜を皮切りに', '~를 시작으로', '〜を始まりとして次々と続く。', 'N1', '名詞 + を皮切りに', '연속 전개의 출발점.', 'time', '[{"ja": "東京を皮切りに全国でセミナーを開催する。", "ko": "도쿄를 시작으로 전국에서 세미나를 개최한다.", "highlight": "東京を皮切りに"}]', '캠페인·투어·전개 서술.', 154),
('〜を機に', '~를 계기로', '〜をきっかけ・転機として。', 'N1', '名詞 + を機に', '「〜を契機に」와 유사.', 'time', '[{"ja": "異動を機に、新しい技術を学び始めた。", "ko": "이동을 계기로 새 기술을 배우기 시작했다.", "highlight": "異動を機に"}]', '전환점 서술.', 155),
('〜ずにはおかない', '반드시 ~하고야 만다', '必ず〜する、または自然にそうさせる。', 'N1', '動詞ない形 + ずにはおかない', 'する→せずにはおかない. 「〜ないではおかない」도.', 'emphasis', '[{"ja": "この作品は観る者を感動させずにはおかない。", "ko": "이 작품은 보는 이를 감동시키고야 만다.", "highlight": "感動させずにはおかない"}]', '강한 필연·자발. 문어.', 156),
('〜を禁じ得ない', '~를 금할 수 없다', '感情を抑えることができない。', 'N1', '名詞 + を禁じ得ない', '감정 명사와 결합. 격식.', 'degree', '[{"ja": "彼の境遇には同情を禁じ得ない。", "ko": "그의 처지에는 동정을 금할 수 없다.", "highlight": "同情を禁じ得ない"}]', '격식 감정 표현(연설·문어).', 157),
('〜極まりない', '더없이 ~하다', 'この上なく〜だ、と程度の極限を表す。', 'N1', 'な形容詞語幹 + 極まりない / 極まる', '「危険極まりない」「失礼極まる」.', 'degree', '[{"ja": "安全を軽視するとは危険極まりない。", "ko": "안전을 경시하다니 더없이 위험하다.", "highlight": "危険極まりない"}]', '강한 부정적 정도.', 158),
('〜だに', '~조차 / ~만 해도', '〜さえ、の硬い表現。', 'N1', '名詞 / 動詞辞書形 + だに', '「想像するだに」「微動だに(しない)」.', 'emphasis', '[{"ja": "そんな事態は想像するだに恐ろしい。", "ko": "그런 사태는 상상만 해도 무섭다.", "highlight": "想像するだに"}]', '문어. 「微動だにしない」 관용.', 159),
('〜にかこつけて', '~를 핑계로', '〜を口実にして、の意。', 'N1', '名詞 + にかこつけて', '구실·핑계. 부정적 뉘앙스.', 'reason', '[{"ja": "出張にかこつけて観光を楽しんだ。", "ko": "출장을 핑계로 관광을 즐겼다.", "highlight": "出張にかこつけて"}]', '핑계 대고 다른 일을 함.', 160);
INSERT INTO jlpt_vocabulary (word, reading, meaning_ko, jlpt_level, part_of_speech, example_sentence, example_sentence_ko) VALUES
('払拭', 'ふっしょく', '불식', 'N1', '명사', '不安を払拭する努力が必要だ。', '불안을 불식시키는 노력이 필요하다.'),
('踏襲', 'とうしゅう', '답습', 'N1', '명사', '前任者の方針を踏襲する。', '전임자의 방침을 답습한다.'),
('逸脱', 'いつだつ', '일탈', 'N1', '명사', '規則からの逸脱は許されない。', '규칙으로부터의 일탈은 허용되지 않는다.'),
('収束', 'しゅうそく', '수습, 수렴', 'N1', '명사', '混乱は徐々に収束に向かった。', '혼란은 서서히 수습으로 향했다.'),
('更迭', 'こうてつ', '경질', 'N1', '명사', '責任者が更迭された。', '책임자가 경질되었다.'),
('隠蔽', 'いんぺい', '은폐', 'N1', '명사', '事実の隠蔽は重大な問題だ。', '사실의 은폐는 중대한 문제다.'),
('漏洩', 'ろうえい', '누설, 유출', 'N1', '명사', '個人情報の漏洩を防ぐ。', '개인정보 유출을 막는다.'),
('該当', 'がいとう', '해당', 'N1', '명사', '該当する項目を選んでください。', '해당하는 항목을 선택해 주세요.'),
('折衷', 'せっちゅう', '절충', 'N1', '명사', '両案を折衷して結論を出した。', '두 안을 절충하여 결론을 냈다.'),
('兼ね合い', 'かねあい', '균형, 조화', 'N1', '명사', 'コストと品質の兼ね合いが難しい。', '비용과 품질의 균형이 어렵다.'),
('配慮', 'はいりょ', '배려', 'N1', '명사', '相手への細やかな配慮が求められる。', '상대에 대한 세심한 배려가 요구된다.'),
('憶測', 'おくそく', '억측', 'N1', '명사', '根拠のない憶測は避けたい。', '근거 없는 억측은 피하고 싶다.'),
('示唆', 'しさ', '시사', 'N1', '명사', '調査結果は重要な点を示唆している。', '조사 결과는 중요한 점을 시사하고 있다.'),
('洞察', 'どうさつ', '통찰', 'N1', '명사', '鋭い洞察に感心した。', '날카로운 통찰에 감탄했다.'),
('看過', 'かんか', '간과', 'N1', '명사', 'この問題は看過できない。', '이 문제는 간과할 수 없다.'),
('過渡期', 'かとき', '과도기', 'N1', '명사', '業界はいま過渡期にある。', '업계는 지금 과도기에 있다.'),
('終焉', 'しゅうえん', '종언, 종말', 'N1', '명사', '一つの時代の終焉を迎えた。', '한 시대의 종언을 맞았다.'),
('確執', 'かくしつ', '알력, 불화', 'N1', '명사', '両者の確執が深まった。', '양측의 불화가 깊어졌다.'),
('歪み', 'ゆがみ', '왜곡, 뒤틀림', 'N1', '명사', '制度の歪みが表面化した。', '제도의 왜곡이 표면화되었다.'),
('過信', 'かしん', '과신', 'N1', '명사', '自分の力を過信してはいけない。', '자신의 힘을 과신해서는 안 된다.'),
('齟齬', 'そご', '어긋남, 괴리', 'N1', '명사', '認識に齟齬が生じている。', '인식에 괴리가 생기고 있다.'),
('賜物', 'たまもの', '산물, 결실', 'N1', '명사', '成功は地道な努力の賜物だ。', '성공은 꾸준한 노력의 산물이다.'),
('根幹', 'こんかん', '근간', 'N1', '명사', '信頼は組織の根幹をなす。', '신뢰는 조직의 근간을 이룬다.'),
('礎', 'いしずえ', '초석, 주춧돌', 'N1', '명사', '彼が会社の礎を築いた。', '그가 회사의 초석을 다졌다.'),
('滲む', 'にじむ', '번지다, 배다', 'N1', '동사', '額に汗が滲む。', '이마에 땀이 밴다.'),
('報いる', 'むくいる', '보답하다', 'N1', '동사', '周囲の期待に報いたい。', '주위의 기대에 보답하고 싶다.'),
('醸す', 'かもす', '자아내다, 빚다', 'N1', '동사', 'その発言は物議を醸した。', '그 발언은 물의를 빚었다.'),
('翻す', 'ひるがえす', '뒤집다, 번복하다', 'N1', '동사', '彼は前言を翻した。', '그는 앞서 한 말을 번복했다.'),
('育む', 'はぐくむ', '기르다, 키우다', 'N1', '동사', '若い才能を育む。', '젊은 재능을 키운다.'),
